    """Build a tree in O(n) time, with children ordered by record ID.

    Record IDs must be unique and cover 0 through len(records) - 1.
    The input sequence is not modified.
    """
    if not records:
        return None

    ordered_records = [None] * len(records)
    for record in records:
        record_id = record.record_id
        parent_id = record.parent_id
        if not isinstance(record_id, int) or not 0 <= record_id < len(records):
            raise ValueError(
                f'Record ID {record_id!r} must be an integer between '
                f'0 and {len(records) - 1}; IDs must be continuous.'
            )
        if ordered_records[record_id] is not None:
            raise ValueError(f'Duplicate record ID: {record_id}.')
        if not isinstance(parent_id, int):
            raise ValueError(f'Parent ID for record {record_id} must be an integer.')
        if record_id == 0:
            if parent_id != 0:
                raise ValueError('Root record (ID 0) must have parent ID 0.')
        elif not 0 <= parent_id < record_id:
            raise ValueError(
                f'Parent ID {parent_id} for record {record_id} must be '
                'non-negative and less than the record ID.'
            )
        ordered_records[record_id] = record

    # Unique, in-range IDs fill every slot, so each parent is guaranteed to exist.
    nodes = [Node(record_id) for record_id in range(len(records))]
    for record in ordered_records[1:]:
        nodes[record.parent_id].children.append(nodes[record.record_id])
    return nodes[0]
